using FluentValidation;
namespace FintechApp.Requests.UpiSender { public class UpdateUpiSenderRequest { public int UpiSenderID { get; set; } public string Name { get; set; } = string.Empty; public string Mobile { get; set; } = string.Empty; public string GUID { get; set; } = string.Empty; public string Address { get; set; } = string.Empty; public int UserID { get; set; } public string IPAddress { get; set; } = string.Empty; public string Pincode { get; set; } = string.Empty; } public class UpdateUpiSenderRequestValidator : AbstractValidator<UpdateUpiSenderRequest> { public UpdateUpiSenderRequestValidator() { RuleFor(x => x.UpiSenderID).GreaterThan(0); } } }
